const apiOrigin = (import.meta.env.VITE_API_URL?.trim() || (import.meta.env.PROD ? "https://api.legacyx.cc" : "")).replace(/\/$/, "")
const banTerms: Array<NonNullable<StaffPanelActionRequest["banTerm"]>> = ["10m", "30m", "1h", "1d", "7d", "permanent"]
const alertColors: Array<NonNullable<StaffPanelActionRequest["alertColor"]>> = ["gold", "sky", "red", "green", "neutral"]
const staffPanelMaps = ["de_ancient", "de_anubis", "de_cache", "de_dust2", "de_inferno", "de_mirage", "de_nuke", "de_overpass", "de_train", "de_vertigo"] as const
const roleOptions: StaffPanelMember["role"][] = ["OWNER", "MANAGER", "ADMIN", "DEVELOPER", "DESIGNER"]
const rolePolicyNumbers: Record<StaffPanelMember["role"], number> = { OWNER: 1000, MANAGER: 750, ADMIN: 500, DEVELOPER: 0, DESIGNER: 0 }
const gamePermissionOptions: StaffPanelMember["gamePermissions"][number][] = ["@css/generic", "@css/kick", "@css/ban", "@css/unban", "@css/slay", "@css/changemap", "@css/chat", "@css/vote", "@css/config", "@css/cvar", "@css/rcon", "@css/cheats", "@css/root"]
type StaffPanelSection = "dashboard" | "live_servers" | "players" | "matches" | "broadcast" | "anti_cheat" | "monitoring" | "announcements" | "logs" | "staff" | "database" | "products" | "promo_codes" | "orders" | "server_management" | "deployments" | "settings" | "audit_logs"
type NavigationItem = { id: StaffPanelSection; label: string; icon: LucideIcon; ownerOnly?: boolean; runtimeStatus?: string }
const staffNavigation: NavigationItem[] = [
  { id: "dashboard", label: "Dashboard", icon: LayoutDashboard }, { id: "live_servers", label: "Live Servers", icon: ServerCog }, { id: "players", label: "Players", icon: UsersRound }, { id: "matches", label: "Matches", icon: Gavel }, { id: "broadcast", label: "Broadcast", icon: Radio, ownerOnly: true, runtimeStatus: "Broadcast, observer, caster and delay telemetry require a scoped reporter." }, { id: "anti_cheat", label: "Anti-Cheat", icon: Shield, runtimeStatus: "Phantom suspension evidence is visible to Manager and Owner only." }, { id: "monitoring", label: "Player Monitoring", icon: Video, ownerOnly: true, runtimeStatus: "Camera, screen and application telemetry are not collected by this panel." }, { id: "announcements", label: "Announcements", icon: Megaphone }, { id: "logs", label: "Logs", icon: ScrollText },
  { id: "staff", label: "Staff Management", icon: UserPlus, ownerOnly: true }, { id: "database", label: "Database", icon: Database, ownerOnly: true }, { id: "products", label: "Products", icon: PackagePlus, ownerOnly: true }, { id: "promo_codes", label: "Promo Codes", icon: TicketPercent, ownerOnly: true, runtimeStatus: "Promo code management is a separate audited Owner workflow." }, { id: "orders", label: "Store / Orders", icon: Store, ownerOnly: true, runtimeStatus: "Store and order operations remain separate from player moderation." }, { id: "server_management", label: "Server Management", icon: Boxes, ownerOnly: true }, { id: "deployments", label: "Deployments", icon: Rocket, ownerOnly: true, runtimeStatus: "Browser deployment or shell controls are intentionally not exposed." }, { id: "settings", label: "System Settings", icon: Settings2, ownerOnly: true }, { id: "audit_logs", label: "Audit Logs", icon: ClipboardList, ownerOnly: true, runtimeStatus: "Staff audit logs require the deferred migration and active staff session data." },
]

type ActionDefinition = { type: StaffPanelActionRequest["type"]; label: string; icon: LucideIcon; scope: "player" | "server"; workflow: "ban" | "reason" | "mute" | "rename" | "hud" | "message" | "map" | "timeout" | "none"; destructive?: boolean }

const managerPlayerActions: ActionDefinition[] = [
  { type: "ban", label: "Ban", icon: Gavel, scope: "player", workflow: "ban", destructive: true },
  { type: "unban", label: "Unban", icon: ShieldCheck, scope: "player", workflow: "reason", destructive: true },
  { type: "kick", label: "Kick", icon: UsersRound, scope: "player", workflow: "reason", destructive: true },
  { type: "mute", label: "Mute", icon: LockKeyhole, scope: "player", workflow: "mute", destructive: true },
  { type: "rename", label: "Rename", icon: UserRoundCog, scope: "player", workflow: "rename" },
  { type: "player_hud_alert", label: "HUD alert", icon: BellRing, scope: "player", workflow: "hud" },
  { type: "player_message", label: "Direct message", icon: MonitorUp, scope: "player", workflow: "message" },
]
const managerServerActions: ActionDefinition[] = [
  { type: "map_change", label: "Map control", icon: Map, scope: "server", workflow: "map", destructive: true },
  { type: "match_announcement", label: "Match announcement", icon: Megaphone, scope: "server", workflow: "message" },
  { type: "hud_announcement", label: "Server HUD alert", icon: MonitorUp, scope: "server", workflow: "hud" },
]
const ownerPlayerActions: ActionDefinition[] = [{ type: "player_ip_lookup", label: "Connection IP", icon: Database, scope: "player", workflow: "none", destructive: true }]
const ownerServerActions: ActionDefinition[] = [
  { type: "server_announcement", label: "Server announcement", icon: Megaphone, scope: "server", workflow: "message" },
  { type: "restart_all", label: "Restart all", icon: Power, scope: "server", workflow: "none", destructive: true },
  { type: "restart_server", label: "Restart server", icon: ServerCog, scope: "server", workflow: "none", destructive: true },
  { type: "start_server", label: "Start server", icon: PlayCircle, scope: "server", workflow: "none", destructive: true },
  { type: "stop_server", label: "Stop server", icon: Power, scope: "server", workflow: "none", destructive: true },
  { type: "timeout", label: "Timeout game", icon: PauseCircle, scope: "server", workflow: "timeout", destructive: true },
  { type: "unpause", label: "Unpause game", icon: PlayCircle, scope: "server", workflow: "none", destructive: true },
  { type: "round_restart", label: "Restart round", icon: RotateCcw, scope: "server", workflow: "none", destructive: true },
  { type: "round_restore", label: "Restore round", icon: RotateCcw, scope: "server", workflow: "none", destructive: true },
]

function toUiError(error: unknown) { return (error as ApiError)?.message || "Unable to complete the requested operation." }
function teamClass(team: StaffPanelRosterPlayer["team"]) { return team === "T" ? "border-amber-300/25 bg-amber-300/[0.06] text-amber-100" : team === "CT" ? "border-sky-300/25 bg-sky-300/[0.06] text-sky-100" : team === "SPECTATOR" ? "border-violet-300/25 bg-violet-300/[0.06] text-violet-100" : "border-border bg-muted/30 text-muted-foreground" }
function teamLabel(team: StaffPanelRosterPlayer["team"]) { return team === "UNASSIGNED" ? "Connected" : team }
function penaltyTone(penalty: PenaltyEntry) { return penalty.isUnbanned ? "border-border bg-muted/40 text-muted-foreground" : penalty.type === "ban" ? "border-red-300/30 bg-red-300/[0.07] text-red-100" : "border-amber-300/30 bg-amber-300/[0.07] text-amber-100" }
function Gauge({ label, value }: { label: string; value: number | null }) { const hasValue = value !== null; const safe = Math.min(100, Math.max(0, value ?? 0)); return <div className="flex items-center gap-3"><div className="grid h-16 w-16 place-items-center rounded-full" style={{ background: hasValue ? `conic-gradient(hsl(var(--primary)) ${safe * 3.6}deg, hsl(var(--muted)) 0deg)` : "repeating-conic-gradient(hsl(var(--muted)) 0 12deg, transparent 12deg 24deg)" }}><div className="grid h-12 w-12 place-items-center rounded-full bg-card text-xs font-semibold text-foreground">{hasValue ? `${Math.round(safe)}%` : "—"}</div></div><div><p className="font-medium text-foreground">{label}</p><p className="text-xs text-muted-foreground">{hasValue ? "Latest telemetry" : "No telemetry received"}</p></div></div> }

export function StaffPanelPage() {
  const [params] = useSearchParams(); const callbackError = params.get("staff_error"); const callbackTrace = params.get("trace"); const [access, setAccess] = useState<StaffPanelAccess | null>(null); const [overview, setOverview] = useState<StaffPanelOverview | null>(null); const [roster, setRoster] = useState<StaffPanelServerRoster | null>(null); const [selectedServer, setSelectedServer] = useState(""); const [selectedPlayer, setSelectedPlayer] = useState<StaffPanelRosterPlayer | null>(null); const [workspaceOpen, setWorkspaceOpen] = useState(false); const [penalties, setPenalties] = useState<PenaltyEntry[]>([]); const [penaltiesLoading, setPenaltiesLoading] = useState(false); const [activeAction, setActiveAction] = useState<ActionDefinition | null>(null); const [pendingAction, setPendingAction] = useState<ActionDefinition | null>(null); const [database, setDatabase] = useState<StaffPanelDatabaseOverview | null>(null); const [products, setProducts] = useState<StaffPanelProduct[]>([]); const [staffDirectory, setStaffDirectory] = useState<StaffPanelMember[]>([]); const [maintenance, setMaintenance] = useState<StaffPanelMaintenance | null>(null); const [health, setHealth] = useState<StaffPanelHealth | null>(null); const [activeSection, setActiveSection] = useState<StaffPanelSection>("dashboard"); const [reason, setReason] = useState(""); const [message, setMessage] = useState(""); const [map, setMap] = useState("de_mirage"); const [mapImpactAcknowledged, setMapImpactAcknowledged] = useState(false); const [banTerm, setBanTerm] = useState<NonNullable<StaffPanelActionRequest["banTerm"]>>("1d"); const [muteDuration, setMuteDuration] = useState("1800"); const [timeoutDuration, setTimeoutDuration] = useState("60"); const [newName, setNewName] = useState(""); const [alertColor, setAlertColor] = useState<NonNullable<StaffPanelActionRequest["alertColor"]>>("gold"); const [countdownSeconds, setCountdownSeconds] = useState("0"); const [notice, setNotice] = useState(""); const [busy, setBusy] = useState(false); const [rosterLoading, setRosterLoading] = useState(false); const [pendingArchive, setPendingArchive] = useState<StaffPanelProduct | null>(null); const [pendingMaintenance, setPendingMaintenance] = useState<boolean | null>(null); const [newStaffUserId, setNewStaffUserId] = useState(""); const [newStaffRole, setNewStaffRole] = useState<StaffPanelMember["role"]>("MANAGER"); const [newStaffPermissions, setNewStaffPermissions] = useState(""); const [productName, setProductName] = useState(""); const [productCategory, setProductCategory] = useState("service"); const [productPrice, setProductPrice] = useState("10")
  const [newStaffGamePermissions, setNewStaffGamePermissions] = useState<StaffPanelMember["gamePermissions"]>([]); const [newStaffStamina, setNewStaffStamina] = useState("0"); const [newStaffImmunity, setNewStaffImmunity] = useState("0"); const [phantomCases, setPhantomCases] = useState<PhantomSuspensionCase[]>([]); const [phantomEvidence, setPhantomEvidence] = useState<PhantomEvidenceEntry[]>([]); const [phantomLoading, setPhantomLoading] = useState(false)
  const actorLabel = access?.role === "OWNER" ? "Owner" : "Manager"; const playerActions = useMemo(() => access?.role === "OWNER" ? [...managerPlayerActions, ...ownerPlayerActions] : managerPlayerActions, [access?.role]); const serverActions = useMemo(() => access?.role === "OWNER" ? [...managerServerActions, ...ownerServerActions] : managerServerActions, [access?.role]); const selectedServerName = roster?.server.name || overview?.servers.find((server) => server.server_id === selectedServer)?.name || selectedServer; const currentMapKey = normalizeCs2MapKey(roster?.server.map || overview?.servers.find((server) => server.server_id === selectedServer)?.map_name); const selectedMapArtwork = cs2MapArtwork(map); const selectedMapIsCurrent = currentMapKey === map; const selectedServerIsLive = roster?.server.state === "live" || roster?.server.state === "paused"

  useEffect(() => { if (!callbackError && params.get("reauth") !== "done") { setAccessToken(null); window.location.replace(`${apiOrigin}/api/v1/auth/steam?staffpanel=1`) } }, [callbackError, params])
  const loadOwnerData = async () => { const [nextDatabase, nextProducts, nextStaff, nextMaintenance, nextHealth] = await Promise.all([staffPanelService.database(), staffPanelService.products(), staffPanelService.staff(), staffPanelService.maintenance(), staffPanelService.health()]); setDatabase(nextDatabase); setProducts(nextProducts); setStaffDirectory(nextStaff); setMaintenance(nextMaintenance); setHealth(nextHealth) }
  const load = async () => { try { const [nextAccess, nextOverview] = await Promise.all([staffPanelService.access(), staffPanelService.overview()]); setAccess(nextAccess); setOverview(nextOverview); setSelectedServer((current) => current || nextOverview.servers[0]?.server_id || ""); if (nextAccess.role === "OWNER") await loadOwnerData() } catch (error) { if ((error as ApiError)?.status === 401) { setAccessToken(null); window.location.replace(`${apiOrigin}/api/v1/auth/steam?staffpanel=1`); return } setNotice(toUiError(error)) } }
  const loadRoster = async (serverId = selectedServer) => { if (!serverId) return; setRosterLoading(true); try { setRoster(await staffPanelService.roster(serverId)) } catch (error) { setRoster(null); setNotice(toUiError(error)) } finally { setRosterLoading(false) } }
  const loadPhantomReview = async () => { setPhantomLoading(true); try { const [cases, evidence] = await Promise.all([staffPanelService.phantomCases(), staffPanelService.phantomEvidence()]); setPhantomCases(cases.cases); setPhantomEvidence(evidence.evidence) } catch (error) { setNotice(toUiError(error)) } finally { setPhantomLoading(false) } }
  const reviewPhantomCase = async (item: PhantomSuspensionCase, decision: "clear" | "keep" | "confirm_ban") => { const note = window.prompt(decision === "confirm_ban" ? "Explain why this suspension is confirmed. A reviewed permanent ban will be queued with a 10-second notice." : "Enter the required review note."); if (!note || note.trim().length < 8) return setNotice("A review note of at least 8 characters is required."); if (!window.confirm(`${decision.replaceAll("_", " ").toUpperCase()} this Phantom case for ${item.steam_id}? This decision is audited.${decision === "confirm_ban" ? " A permanent ban is only queued after this explicit confirmation." : ""}`)) return; setBusy(true); try { await staffPanelService.reviewPhantomCase(item.id, { decision, note: note.trim() }); setNotice(`Phantom case ${decision.replaceAll("_", " ")} has been audited.`); await loadPhantomReview() } catch (error) { setNotice(toUiError(error)) } finally { setBusy(false) } }
  useEffect(() => { if (params.get("reauth") === "done") void load() }, [params]); useEffect(() => { setSelectedPlayer(null); setWorkspaceOpen(false); setActiveAction(null); setPendingAction(null); setRoster(null); if (selectedServer) void loadRoster(selectedServer) }, [selectedServer]); useEffect(() => { if (access && activeSection === "anti_cheat") void loadPhantomReview() }, [access, activeSection])
  const selectPlayer = async (player: StaffPanelRosterPlayer) => { setSelectedPlayer(player); setWorkspaceOpen(true); setActiveAction(null); setPenaltiesLoading(true); try { const result = await staffPanelService.playerPenalties(player.steamId); setPenalties(result.penalties) } catch (error) { setPenalties([]); setNotice(toUiError(error)) } finally { setPenaltiesLoading(false) } }
  const resetActionFields = () => { setReason(""); setMessage(""); setNewName(""); setAlertColor("gold"); setCountdownSeconds("0"); setMuteDuration("1800"); setTimeoutDuration("60") }
  const chooseAction = (action: ActionDefinition) => { if (action.scope === "player" && !selectedPlayer) return setNotice("Select a player from the roster first."); resetActionFields(); if (action.type === "map_change") { const current = currentMapKey && staffPanelMaps.includes(currentMapKey as typeof staffPanelMaps[number]) ? currentMapKey : null; setMap(current || "de_mirage"); setMapImpactAcknowledged(false) } setActiveAction(action); setNotice("") }
  const requestConfirmation = () => { if (!activeAction) return; if (activeAction.scope === "player" && !selectedPlayer) return setNotice("Select a player from the roster first."); if (activeAction.workflow === "ban" && !reason.trim()) return setNotice("A ban reason is required."); if (["reason", "mute"].includes(activeAction.workflow) && !reason.trim()) return setNotice("A reason is required."); if (["hud", "message"].includes(activeAction.workflow) && !message.trim()) return setNotice("Text is required for this alert or message."); if (activeAction.workflow === "map" && (!staffPanelMaps.includes(map as typeof staffPanelMaps[number]) || selectedMapIsCurrent || !mapImpactAcknowledged)) return setNotice("Choose a different approved map and acknowledge its impact."); if (activeAction.workflow === "timeout" && (!Number.isInteger(Number(timeoutDuration)) || Number(timeoutDuration) < 10 || Number(timeoutDuration) > 86400)) return setNotice("Timeout duration must be 10–86400 seconds."); if (activeAction.workflow === "rename" && newName.trim().length < 2) return setNotice("Enter the player’s new name."); if (activeAction.workflow === "hud" && (!Number.isInteger(Number(countdownSeconds)) || Number(countdownSeconds) < 0 || Number(countdownSeconds) > 600)) return setNotice("Countdown must be between 0 and 600 seconds."); setPendingAction(activeAction) }
  const queuePendingAction = async () => { if (!pendingAction) return; setBusy(true); const moderationReason = ["ban", "unban", "kick", "mute"].includes(pendingAction.type) ? reason.trim() : undefined; try { const result = await staffPanelService.queueAction({ serverId: selectedServer, type: pendingAction.type, playerSteamId: selectedPlayer?.steamId, playerName: selectedPlayer?.name, message: moderationReason || message.trim() || undefined, reason: moderationReason, map: pendingAction.workflow === "map" ? map : undefined, mapImpactAcknowledged: pendingAction.workflow === "map" ? true : undefined, durationSeconds: pendingAction.type === "mute" ? Number(muteDuration) : pendingAction.type === "timeout" ? Number(timeoutDuration) : undefined, banTerm: pendingAction.type === "ban" ? banTerm : undefined, enforceAfterSeconds: pendingAction.type === "ban" ? 10 : undefined, alertColor: pendingAction.workflow === "hud" ? alertColor : undefined, countdownSeconds: pendingAction.workflow === "hud" ? Number(countdownSeconds) : undefined, newName: pendingAction.type === "rename" ? newName.trim() : undefined }); setNotice(`${result.action.action_type.replaceAll("_", " ")} is queued and audited. Plugin acknowledgement is still required.`); setPendingAction(null); setActiveAction(null); setWorkspaceOpen(false); await Promise.all([load(), loadRoster()]) } catch (error) { setNotice(toUiError(error)) } finally { setBusy(false) } }
  const createProduct = async () => { if (!productName.trim() || !Number.isInteger(Number(productPrice)) || Number(productPrice) < 0) return setNotice("Enter a valid product name and whole coin price."); setBusy(true); try { await staffPanelService.createProduct({ name: productName.trim(), category: productCategory.trim() || "service", price: Number(productPrice), image: "", rarity: "Common" }); setProductName(""); setNotice("Product created and audited."); await loadOwnerData() } catch (error) { setNotice(toUiError(error)) } finally { setBusy(false) } }
  const archiveProduct = async () => { if (!pendingArchive) return; setBusy(true); try { await staffPanelService.archiveProduct(pendingArchive.id); setPendingArchive(null); setNotice("Product archived. Purchase history remains intact."); await loadOwnerData() } catch (error) { setNotice(toUiError(error)) } finally { setBusy(false) } }
  const createStaff = async () => { if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(newStaffUserId)) return setNotice("Enter the existing user UUID for the new staff record."); const stamina = Number(newStaffStamina); const immunity = Number(newStaffImmunity); if (!Number.isInteger(stamina) || stamina < 0 || stamina > 1000 || !Number.isInteger(immunity) || immunity < 0 || immunity > 1000) return setNotice("In-game stamina and immunity must be whole values between 0 and 1000."); setBusy(true); try { await staffPanelService.createStaff({ userId: newStaffUserId, role: newStaffRole, permissions: newStaffPermissions.split(",").map((item) => item.trim()).filter(Boolean), gamePermissions: newStaffGamePermissions, stamina, immunity, status: "active" }); setNewStaffUserId(""); setNewStaffPermissions(""); setNewStaffGamePermissions([]); setNewStaffStamina("0"); setNewStaffImmunity("0"); setNotice("Staff record created and audited."); await loadOwnerData() } catch (error) { setNotice(toUiError(error)) } finally { setBusy(false) } }
  const updateStaff = async (member: StaffPanelMember, changes: Partial<Pick<StaffPanelMember, "role" | "permissions" | "gamePermissions" | "stamina" | "immunity" | "status">>) => { setBusy(true); try { await staffPanelService.updateStaff(member.id, changes); setNotice("Staff role, stamina, game permission or immunity configuration is audited."); await loadOwnerData() } catch (error) { setNotice(toUiError(error)) } finally { setBusy(false) } }
  const requestGamePolicyUpdate = (member: StaffPanelMember, changes: Partial<Pick<StaffPanelMember, "gamePermissions" | "stamina" | "immunity">>) => { const nextPermissions = changes.gamePermissions || member.gamePermissions; const nextStamina = changes.stamina ?? member.stamina; const nextImmunity = changes.immunity ?? member.immunity; const dangerousPermissionAdded = ["@css/root", "@css/rcon", "@css/cvar", "@css/cheats"].some((permission) => nextPermissions.includes(permission as StaffPanelMember["gamePermissions"][number]) && !member.gamePermissions.includes(permission as StaffPanelMember["gamePermissions"][number])); const entersTopTier = (nextStamina === 1000 && member.stamina !== 1000) || (nextImmunity === 1000 && member.immunity !== 1000); if ((dangerousPermissionAdded || entersTopTier) && !window.confirm(`Confirm high-impact in-game policy change for ${member.username || member.userId}. This change is audited and will be pulled by the game server.`)) return; void updateStaff(member, changes) }
  const saveMaintenance = async () => { if (pendingMaintenance === null) return; setBusy(true); try { await staffPanelService.updateMaintenance({ website: "legacyx.cc", enabled: pendingMaintenance }); setPendingMaintenance(null); setNotice("Maintenance configuration intent is saved and audited. Public website runtime rollout is still required."); await loadOwnerData() } catch (error) { setNotice(toUiError(error)) } finally { setBusy(false) } }
  if (callbackError) return <main className="mx-auto flex min-h-[65vh] w-full max-w-xl items-center p-4"><Card className="w-full border-border bg-card/90 backdrop-blur-xl"><CardHeader><CardTitle className="flex items-center gap-2"><AlertTriangle className="h-5 w-5 text-primary" />Staff session could not start</CardTitle><CardDescription>{callbackError === "staff_setup_required" ? "Staff Panel access is temporarily unavailable. The server configuration or staff-session database setup requires review." : "Steam verification could not complete. Please retry the isolated Staff Panel sign-in."}</CardDescription></CardHeader><CardContent className="space-y-4"><div className="rounded-lg border border-border bg-muted/30 p-3 text-xs leading-5 text-muted-foreground">No sensitive server detail is shown here. {callbackTrace ? <>Support trace: <span className="font-mono text-foreground">{callbackTrace}</span></> : ""}</div><Button onClick={() => window.location.replace(`${apiOrigin}/api/v1/auth/steam?staffpanel=1`)} className="w-full">Retry Staff Panel sign-in</Button><Button variant="outline" onClick={() => window.location.replace("/")} className="w-full">Return home</Button></CardContent></Card></main>
  if (!access) return <div className="flex min-h-[65vh] items-center justify-center gap-3 text-sm text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" />Steam re-authentication required</div>

  const isOwner = access.role === "OWNER"; const visibleNavigation = staffNavigation.filter((item) => isOwner || !item.ownerOnly); const activeNavigation = staffNavigation.find((item) => item.id === activeSection); const commandVisible = ["dashboard", "live_servers", "players", "matches", "announcements", "logs"].includes(activeSection)
  return <main className="mx-auto w-full max-w-7xl space-y-5 p-4 md:p-7"><section className="relative overflow-hidden rounded-2xl border border-border bg-card/90 p-6 shadow-sm backdrop-blur-xl"><div className="absolute right-0 top-0 h-40 w-80 bg-white/[0.035] blur-3xl" /><div className="relative flex flex-col gap-4 md:flex-row md:items-end md:justify-between"><div><p className="text-xs font-semibold uppercase tracking-[.22em] text-muted-foreground">Isolated Steam staff session</p><h1 className="mt-2 text-3xl font-semibold tracking-tight text-foreground">Staff Panel</h1><p className="mt-2 text-sm text-muted-foreground">{access.username} · <span className="text-foreground">{access.role}</span> access</p></div><div className="max-w-sm rounded-lg border border-border bg-background/35 px-4 py-3 text-xs leading-5 text-muted-foreground">All privileged operations are confirmation-gated, audited, allowlisted and remain pending until a scoped executor acknowledges them.</div></div></section>
    <nav className="rounded-xl border border-border bg-card/80 p-2 backdrop-blur-xl" aria-label="Staff panel navigation"><div className="flex gap-1 overflow-x-auto pb-1">{visibleNavigation.map((item) => { const Icon = item.icon; return <Button key={item.id} type="button" size="sm" variant={activeSection === item.id ? "default" : "ghost"} onClick={() => setActiveSection(item.id)} className="shrink-0 gap-2"><Icon className="h-4 w-4" />{item.label}</Button> })}</div></nav>
    {notice && <div className="rounded-lg border border-border bg-card/70 px-4 py-3 text-sm text-foreground backdrop-blur-md">{notice}</div>}

    {commandVisible && <><section className="grid gap-4 xl:grid-cols-[1.25fr_.75fr]"><Card className="bg-card/90 backdrop-blur-xl"><CardHeader className="pb-3"><CardTitle className="flex items-center gap-2"><UsersRound className="h-4 w-4" />Server roster</CardTitle><CardDescription>Select a server, then select one player to open the foreground action workspace.</CardDescription></CardHeader><CardContent><div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-end"><div className="min-w-0 flex-1"><Label className="mb-1.5 block" htmlFor="staff-server">Target server</Label><select id="staff-server" value={selectedServer} onChange={(event) => setSelectedServer(event.target.value)} className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm text-foreground"><option value="">Select server</option>{overview?.servers.map((server) => <option key={server.server_id} value={server.server_id}>{server.name || server.server_id} · {server.mode} · {server.map_name}</option>)}</select></div><Button type="button" variant="outline" disabled={!selectedServer || rosterLoading} onClick={() => void loadRoster()} className="gap-2"><RefreshCw className={`h-4 w-4 ${rosterLoading ? "animate-spin" : ""}`} />Refresh</Button></div>{roster && <div className="mb-3 flex flex-wrap items-center justify-between gap-2 rounded-lg border border-border bg-muted/30 px-3 py-2 text-xs text-muted-foreground"><span>{roster.server.name} · {roster.server.mode} · {roster.server.map}</span><span>{roster.players.length} visible · {roster.server.availability.replaceAll("_", " ")}</span></div>}{rosterLoading && <div className="flex min-h-44 items-center justify-center gap-2 text-sm text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" />Loading roster</div>}{!rosterLoading && !roster && <div className="flex min-h-44 items-center justify-center text-center text-sm text-muted-foreground">Choose a server to load its current player roster.</div>}{!rosterLoading && roster && <div className="overflow-hidden rounded-lg border border-border"><Table><TableHeader><TableRow><TableHead>Player</TableHead><TableHead>Team</TableHead><TableHead className="text-right">ADR</TableHead><TableHead className="text-right">Ping</TableHead></TableRow></TableHeader><TableBody>{roster.players.length ? roster.players.map((player) => <TableRow key={`${player.steamId}-${player.team}`} onClick={() => void selectPlayer(player)} className="cursor-pointer transition-colors hover:bg-muted/60"><TableCell><div className="flex min-w-0 flex-col"><span className="truncate font-medium text-foreground">{player.name}</span><span className="font-mono text-[10px] text-muted-foreground">{player.steamId}</span></div></TableCell><TableCell><span className={`inline-flex rounded-full border px-2 py-0.5 text-[10px] font-semibold ${teamClass(player.team)}`}>{teamLabel(player.team)}</span></TableCell><TableCell className="text-right text-xs tabular-nums text-muted-foreground">{player.adr === null ? "—" : player.adr.toFixed(1)}</TableCell><TableCell className="text-right text-xs tabular-nums text-muted-foreground">{player.ping === null ? "—" : `${player.ping}ms`}</TableCell></TableRow>) : <TableRow><TableCell colSpan={4} className="h-24 text-center text-sm text-muted-foreground">No current player snapshot received.</TableCell></TableRow>}</TableBody></Table></div>}</CardContent></Card>
        <Card className="bg-card/90 backdrop-blur-xl"><CardHeader className="pb-3"><CardTitle>Server controls</CardTitle><CardDescription>Manager sees only operational controls. Owner-only controls are excluded from Manager view.</CardDescription></CardHeader><CardContent className="space-y-4"><div className="grid grid-cols-2 gap-2">{serverActions.map((action) => { const Icon = action.icon; return <Button key={action.type} type="button" disabled={!selectedServer || busy} onClick={() => chooseAction(action)} variant={action.destructive ? "outline" : "secondary"} className="h-auto justify-start gap-2 px-3 py-3 text-left"><Icon className="h-4 w-4 shrink-0" />{action.label}</Button> })}</div><div className="rounded-lg border border-border bg-background/35 p-3 text-xs leading-5 text-muted-foreground"><p className="font-medium text-foreground">Action queue</p>{overview?.pendingActions.length ? <div className="mt-2 space-y-1.5">{overview.pendingActions.slice(0, 4).map((action) => <div key={action.id} className="flex justify-between gap-3"><span className="min-w-0 truncate">{action.action_type.replaceAll("_", " ")}</span><span className="uppercase">{action.status}</span></div>)}</div> : <p className="mt-1">No pending operations.</p>}</div></CardContent></Card></section>
      {activeAction?.scope === "server" && <Card className="border-primary/25 bg-card/90 backdrop-blur-xl"><CardHeader className="pb-3"><CardTitle className="flex items-center gap-2"><activeAction.icon className="h-4 w-4 text-primary" />Configure {activeAction.label}</CardTitle><CardDescription>Target server: {selectedServerName}</CardDescription></CardHeader><CardContent className="space-y-4">{activeAction.workflow === "map" && <div className="space-y-4"><div className="overflow-hidden rounded-xl border border-border bg-muted/20"><div className="grid gap-0 md:grid-cols-[.78fr_1.22fr]">{selectedMapArtwork ? <img src={selectedMapArtwork} alt={`${cs2MapLabel(map)} map artwork`} className="h-40 w-full object-cover opacity-80 md:h-full" /> : <div className="flex min-h-40 items-center justify-center bg-muted text-muted-foreground"><Map className="h-7 w-7" /></div>}<div className="p-4"><p className="text-xs font-semibold uppercase tracking-[.16em] text-muted-foreground">Target map</p><h3 className="mt-1 text-xl font-semibold text-foreground">{cs2MapLabel(map)}</h3><dl className="mt-3 grid gap-2 text-sm"><div className="flex justify-between gap-3"><dt className="text-muted-foreground">Current</dt><dd>{currentMapKey ? cs2MapLabel(currentMapKey) : "Unavailable"}</dd></div><div className="flex justify-between gap-3"><dt className="text-muted-foreground">State</dt><dd>{roster?.server.state || "unavailable"}</dd></div><div className="flex justify-between gap-3"><dt className="text-muted-foreground">Visible players</dt><dd>{roster?.players.length ?? 0}</dd></div></dl></div></div></div><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{staffPanelMaps.map((key) => <Button key={key} type="button" variant="outline" aria-pressed={map === key} onClick={() => { setMap(key); setMapImpactAcknowledged(false) }} className={`h-auto min-h-16 justify-start gap-2 p-2 text-left ${map === key ? "border-primary bg-primary/10" : ""}`}><img src={cs2MapArtwork(key) || ""} alt="" className="h-11 w-16 rounded object-cover opacity-80" /><span>{cs2MapLabel(key)}</span></Button>)}</div><div className={`rounded-lg border p-3 ${selectedServerIsLive ? "border-amber-300/30 bg-amber-300/[0.07]" : "border-border bg-muted/30"}`}><div className="flex items-start gap-3"><Checkbox id="map-impact" checked={mapImpactAcknowledged} onCheckedChange={(checked) => setMapImpactAcknowledged(checked === true)} /><div><Label htmlFor="map-impact" className="cursor-pointer font-medium text-foreground">I understand that changing the map interrupts the selected server.</Label><p className="mt-1 text-xs leading-5 text-muted-foreground">{selectedServerIsLive ? "An active or paused match is reported. The executor revalidates state before transition." : "The executor still validates server availability and map support."}</p></div></div></div></div>}{activeAction.workflow === "timeout" && <div className="max-w-sm"><Label className="mb-1.5 block" htmlFor="timeout-duration">Timeout duration in seconds</Label><Input id="timeout-duration" value={timeoutDuration} onChange={(event) => setTimeoutDuration(event.target.value)} inputMode="numeric" /><p className="mt-1.5 text-xs text-muted-foreground">10–86400 seconds. A scoped executor must acknowledge the actual match pause.</p></div>}{["hud", "message"].includes(activeAction.workflow) && <div className="space-y-3"><Label className="mb-1.5 block" htmlFor="server-message">{activeAction.workflow === "hud" ? "HUD text" : "Message"}</Label><Textarea id="server-message" value={message} onChange={(event) => setMessage(event.target.value)} placeholder="Write player-facing text" />{activeAction.workflow === "hud" && <div className="grid gap-3 sm:grid-cols-2"><div><Label className="mb-1.5 block">Alert color</Label><div className="flex flex-wrap gap-2">{alertColors.map((color) => <Button key={color} type="button" variant={alertColor === color ? "default" : "outline"} onClick={() => setAlertColor(color)} className="capitalize">{color}</Button>)}</div></div><div><Label className="mb-1.5 block" htmlFor="server-countdown">Optional countdown seconds</Label><Input id="server-countdown" value={countdownSeconds} onChange={(event) => setCountdownSeconds(event.target.value)} inputMode="numeric" /></div></div>}</div>}{activeAction.workflow === "none" && <div className="rounded-lg border border-border bg-muted/30 p-3 text-sm text-muted-foreground">No raw command field is exposed. Review the exact target in the confirmation dialog.</div>}<div className="flex justify-end gap-2 border-t border-border pt-4"><Button type="button" variant="outline" onClick={() => setActiveAction(null)}>Cancel</Button><Button type="button" onClick={requestConfirmation}>Review and confirm</Button></div></CardContent></Card>}</>}

    {isOwner && activeSection === "staff" && <section className="grid gap-4 xl:grid-cols-[1.15fr_.85fr]">
      <Card className="bg-card/90 backdrop-blur-xl"><CardHeader><CardTitle className="flex items-center gap-2"><UsersRound className="h-4 w-4" />Staff directory</CardTitle><CardDescription>Separate staff records only. `users.role` is not edited by this panel.</CardDescription></CardHeader><CardContent className="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>Member</TableHead><TableHead>Role</TableHead><TableHead>Permissions</TableHead><TableHead>Status</TableHead></TableRow></TableHeader><TableBody>{staffDirectory.map((member) => <TableRow key={member.id}><TableCell><p className="font-medium text-foreground">{member.username || member.userId}</p><p className="font-mono text-[10px] text-muted-foreground">{member.steamId || member.userId}</p></TableCell><TableCell><select value={member.role} disabled={busy} onChange={(event) => void updateStaff(member, { role: event.target.value as StaffPanelMember["role"] })} className="rounded-md border border-input bg-background px-2 py-1 text-xs">{roleOptions.map((role) => <option key={role}>{role}</option>)}</select></TableCell><TableCell><Input defaultValue={member.permissions.join(", ")} onBlur={(event) => { const permissions = event.target.value.split(",").map((item) => item.trim()).filter(Boolean); if (permissions.join(",") !== member.permissions.join(",")) void updateStaff(member, { permissions }) }} className="min-w-48 text-xs" placeholder="map_change, ban" /></TableCell><TableCell><select value={member.status} disabled={busy} onChange={(event) => void updateStaff(member, { status: event.target.value as StaffPanelMember["status"] })} className="rounded-md border border-input bg-background px-2 py-1 text-xs"><option value="active">active</option><option value="suspended">suspended</option><option value="revoked">revoked</option></select></TableCell></TableRow>)}</TableBody></Table></CardContent></Card>
      <Card className="bg-card/90 backdrop-blur-xl"><CardHeader><CardTitle className="flex items-center gap-2"><UserPlus className="h-4 w-4" />Add staff record</CardTitle><CardDescription>Role selects the suggested numeric baseline. Explicit game permissions stay opt-in.</CardDescription></CardHeader><CardContent className="space-y-3"><div><Label className="mb-1.5 block" htmlFor="staff-user-id">User UUID</Label><Input id="staff-user-id" value={newStaffUserId} onChange={(event) => setNewStaffUserId(event.target.value)} placeholder="Existing users.id" /></div><div><Label className="mb-1.5 block" htmlFor="staff-role">Role</Label><select id="staff-role" value={newStaffRole} onChange={(event) => { const role = event.target.value as StaffPanelMember["role"]; const baseline = rolePolicyNumbers[role]; setNewStaffRole(role); setNewStaffStamina(String(baseline)); setNewStaffImmunity(String(baseline)) }} className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm">{roleOptions.map((role) => <option key={role}>{role}</option>)}</select></div><div className="grid grid-cols-2 gap-3"><div><Label className="mb-1.5 block" htmlFor="staff-stamina">Stamina</Label><Input id="staff-stamina" value={newStaffStamina} inputMode="numeric" onChange={(event) => setNewStaffStamina(event.target.value)} /></div><div><Label className="mb-1.5 block" htmlFor="staff-immunity">Immunity</Label><Input id="staff-immunity" value={newStaffImmunity} inputMode="numeric" onChange={(event) => setNewStaffImmunity(event.target.value)} /></div></div><div><Label className="mb-1.5 block" htmlFor="staff-permissions">Website permissions</Label><Input id="staff-permissions" value={newStaffPermissions} onChange={(event) => setNewStaffPermissions(event.target.value)} placeholder="ban, map_change or *" /></div><div><Label className="mb-1.5 block">In-game permissions</Label><div className="flex flex-wrap gap-1.5">{gamePermissionOptions.map((permission) => { const enabled = newStaffGamePermissions.includes(permission); return <Button key={permission} type="button" size="sm" variant={enabled ? "default" : "outline"} onClick={() => setNewStaffGamePermissions(enabled ? newStaffGamePermissions.filter((value) => value !== permission) : [...newStaffGamePermissions, permission])}>{permission.replace("@css/", "")}</Button> })}</div></div><Button disabled={busy} onClick={() => void createStaff()} className="w-full">Create audited staff record</Button></CardContent></Card>
    </section>}
    {isOwner && activeSection === "staff" && <Card className="bg-card/90 backdrop-blur-xl"><CardHeader><CardTitle className="flex items-center gap-2"><ShieldCheck className="h-4 w-4" />In-game admin policy</CardTitle><CardDescription>Website is authoritative. Stamina controls command thresholds; immunity controls target precedence; explicit CounterStrikeSharp permissions remain mandatory.</CardDescription></CardHeader><CardContent className="space-y-3">{staffDirectory.length ? staffDirectory.map((member) => <div key={`game-policy-${member.id}`} className="rounded-xl border border-border bg-background/35 p-4"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="font-medium text-foreground">{member.username || member.userId}</p><p className="font-mono text-[10px] text-muted-foreground">{member.steamId || "Steam identity unavailable"} · {member.status} · suggested {rolePolicyNumbers[member.role]}/1000</p></div><div className="grid w-full grid-cols-2 gap-3 sm:w-72"><div><Label className="mb-1 block text-xs" htmlFor={`stamina-${member.id}`}>Stamina 0–1000</Label><Input id={`stamina-${member.id}`} defaultValue={String(member.stamina)} inputMode="numeric" onBlur={(event) => { const stamina = Number(event.target.value); if (Number.isInteger(stamina) && stamina >= 0 && stamina <= 1000 && stamina !== member.stamina) requestGamePolicyUpdate(member, { stamina }) }} /></div><div><Label className="mb-1 block text-xs" htmlFor={`immunity-${member.id}`}>Immunity 0–1000</Label><Input id={`immunity-${member.id}`} defaultValue={String(member.immunity)} inputMode="numeric" onBlur={(event) => { const immunity = Number(event.target.value); if (Number.isInteger(immunity) && immunity >= 0 && immunity <= 1000 && immunity !== member.immunity) requestGamePolicyUpdate(member, { immunity }) }} /></div></div></div><div className="mt-3 flex flex-wrap gap-2">{gamePermissionOptions.map((permission) => { const enabled = member.gamePermissions.includes(permission); return <Button key={permission} type="button" size="sm" variant={enabled ? "default" : "outline"} disabled={busy || member.status !== "active"} onClick={() => requestGamePolicyUpdate(member, { gamePermissions: enabled ? member.gamePermissions.filter((value) => value !== permission) : [...member.gamePermissions, permission] })}>{permission.replace("@css/", "")}</Button> })}</div></div>) : <p className="rounded-lg border border-border bg-muted/30 p-4 text-sm text-muted-foreground">No staff records exist yet.</p>}<p className="rounded-lg border border-border bg-muted/20 p-3 text-xs leading-5 text-muted-foreground">Role baselines are Owner 1000, Manager 750, Admin 500 and non-admin roles 0. Root, RCON, CVar, Cheats, stamina 1000 and immunity 1000 require an explicit confirmation. No permission is inferred from role, stamina or immunity.</p></CardContent></Card>}
    {isOwner && ["database", "products", "settings", "server_management"].includes(activeSection) && <section className="grid gap-4 xl:grid-cols-[1.05fr_.95fr]"><Card className="bg-card/90 backdrop-blur-xl"><CardHeader><CardTitle className="flex items-center gap-2"><Activity className="h-4 w-4" />VPS health</CardTitle><CardDescription>Telemetry stays unavailable until a scoped reporter writes live server-health snapshots.</CardDescription></CardHeader><CardContent><div className="grid gap-4 sm:grid-cols-3"><Gauge label="CPU" value={health?.cpuPercent ?? null} /><Gauge label="Memory" value={health?.memoryPercent ?? null} /><Gauge label="Disk" value={health?.diskPercent ?? null} /></div><div className="mt-5 rounded-lg border border-border bg-background/35 p-3 text-xs text-muted-foreground"><p>State: <span className="text-foreground">{health?.availability === "telemetry" ? health.healthy ? "healthy" : "degraded" : "telemetry unavailable"}</span></p><p className="mt-1">Load average: {health?.loadAverage ?? "—"} · Updated: {health?.updatedAt ? new Date(health.updatedAt).toLocaleString() : "—"}</p><p className="mt-1">Database overview: {database ? `${database.tables.reduce((total, table) => total + table.count, 0).toLocaleString()} indexed records across ${database.tables.length} audited tables` : "unavailable"}</p></div></CardContent></Card><Card className="bg-card/90 backdrop-blur-xl"><CardHeader><CardTitle className="flex items-center gap-2"><Settings2 className="h-4 w-4" />Website maintenance</CardTitle><CardDescription>Audited configuration intent. It does not change the public website until the production runtime consumes this setting.</CardDescription></CardHeader><CardContent className="space-y-4"><div><Label className="mb-1.5 block" htmlFor="website-target">Website</Label><select id="website-target" value="legacyx.cc" disabled className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm"><option value="legacyx.cc">legacyx.cc</option></select></div><div className="rounded-lg border border-border bg-background/35 p-3"><p className="font-medium text-foreground">Maintenance intent</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Current saved state: {maintenance?.availability === "configured" ? maintenance.enabled ? "enabled" : "disabled" : "not configured"}</p></div><Button variant={maintenance?.enabled ? "outline" : "default"} disabled={busy} onClick={() => setPendingMaintenance(!(maintenance?.enabled ?? false))} className="w-full">{maintenance?.enabled ? "Request maintenance off" : "Request maintenance on"}</Button></CardContent></Card><Card className="xl:col-span-2 bg-card/90 backdrop-blur-xl"><CardHeader><CardTitle className="flex items-center gap-2"><PackagePlus className="h-4 w-4" />Products</CardTitle><CardDescription>Owner-only catalog work. Deployment controls remain outside the browser.</CardDescription></CardHeader><CardContent><div className="grid gap-2 sm:grid-cols-[1fr_.8fr_.5fr_auto]"><Input value={productName} onChange={(event) => setProductName(event.target.value)} placeholder="Product name" /><Input value={productCategory} onChange={(event) => setProductCategory(event.target.value)} placeholder="Category" /><Input value={productPrice} onChange={(event) => setProductPrice(event.target.value)} inputMode="numeric" placeholder="Coins" /><Button disabled={busy} onClick={() => void createProduct()} size="sm">Add</Button></div><div className="mt-3 space-y-2">{products.slice(0, 5).map((product) => <div key={product.id} className="flex items-center justify-between gap-3 rounded-lg border border-border px-3 py-2 text-sm"><span className="min-w-0 truncate text-foreground">{product.name}</span><span className="text-muted-foreground">{product.active ? `${product.price} coins` : "archived"}</span>{product.active && <Button disabled={busy} onClick={() => setPendingArchive(product)} variant="outline" size="sm">Archive</Button>}</div>)}</div></CardContent></Card></section>}
    {activeSection === "anti_cheat" && <section className="space-y-4"><Card className="border-red-300/20 bg-card/90 backdrop-blur-xl"><CardHeader><CardTitle className="flex items-center gap-2"><ShieldAlert className="h-4 w-4 text-red-300" />Phantom suspension review</CardTitle><CardDescription>Evidence is review-only. Clearing and keeping a suspension require an audited note; confirming queues a separate permanent-ban action with its existing 10-second player notice.</CardDescription></CardHeader><CardContent>{phantomLoading ? <div className="flex min-h-32 items-center justify-center gap-2 text-sm text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" />Loading authoritative Phantom cases</div> : <div className="overflow-x-auto rounded-lg border border-border"><Table><TableHeader><TableRow><TableHead>Subject</TableHead><TableHead>Score</TableHead><TableHead>Evidence</TableHead><TableHead>Status</TableHead><TableHead className="text-right">Review</TableHead></TableRow></TableHeader><TableBody>{phantomCases.length ? phantomCases.map((item) => <TableRow key={item.id}><TableCell><p className="font-mono text-xs text-foreground">{item.steam_id}</p><p className="text-[10px] text-muted-foreground">{item.server_id} · round evidence: {item.evidence_count}</p></TableCell><TableCell className="font-semibold text-amber-200">{item.suspicion_score.toFixed(1)}</TableCell><TableCell className="text-xs text-muted-foreground">{item.evidence_summary.latest_interaction || "—"} · {Math.round((item.evidence_summary.evidence_confidence || 0) * 100)}%</TableCell><TableCell><span className={`rounded-full border px-2 py-1 text-[10px] font-semibold ${item.status === "SUSPENDED" ? "border-red-300/30 bg-red-300/[.08] text-red-200" : "border-border bg-muted/30 text-muted-foreground"}`}>{item.status}</span></TableCell><TableCell><div className="flex justify-end gap-1"><Button size="sm" variant="outline" disabled={busy || item.status !== "SUSPENDED"} onClick={() => void reviewPhantomCase(item, "clear")}>Clear</Button><Button size="sm" variant="outline" disabled={busy || item.status !== "SUSPENDED"} onClick={() => void reviewPhantomCase(item, "keep")}>Keep</Button><Button size="sm" variant="destructive" disabled={busy || item.status !== "SUSPENDED"} onClick={() => void reviewPhantomCase(item, "confirm_ban")}>Confirm ban</Button></div></TableCell></TableRow>) : <TableRow><TableCell colSpan={5} className="h-24 text-center text-sm text-muted-foreground">No Phantom suspension cases have been received.</TableCell></TableRow>}</TableBody></Table></div>}</CardContent></Card><Card className="bg-card/90 backdrop-blur-xl"><CardHeader><CardTitle className="flex items-center gap-2"><History className="h-4 w-4" />Phantom evidence timeline</CardTitle><CardDescription>Raw evidence signals remain available for investigation and do not by themselves trigger a ban.</CardDescription></CardHeader><CardContent>{phantomEvidence.length ? <div className="space-y-2">{phantomEvidence.slice(0, 20).map((item) => <div key={item.id} className="flex flex-col justify-between gap-2 rounded-lg border border-border bg-background/30 p-3 text-xs sm:flex-row sm:items-center"><span className="font-mono text-foreground">{item.steam_id}</span><span className="text-muted-foreground">{item.interaction_type} · round {item.round_number} · score {item.suspicion_score.toFixed(1)} · confidence {Math.round(item.evidence_confidence * 100)}%</span><span className="text-muted-foreground">{new Date(item.occurred_at).toLocaleString()}</span></div>)}</div> : <p className="rounded-lg border border-border bg-muted/30 p-4 text-sm text-muted-foreground">No Phantom evidence has been received.</p>}</CardContent></Card></section>}
    {!commandVisible && activeSection !== "anti_cheat" && !(isOwner && (activeSection === "staff" || ["database", "products", "settings", "server_management"].includes(activeSection))) && <Card className="bg-card/90 backdrop-blur-xl"><CardHeader><CardTitle className="flex items-center gap-2">{activeNavigation && <activeNavigation.icon className="h-4 w-4" />}{activeNavigation?.label || "Staff section"}</CardTitle><CardDescription>{activeNavigation?.runtimeStatus || "This permission-scoped section is available in the Staff Panel navigation."}</CardDescription></CardHeader><CardContent><div className="rounded-lg border border-border bg-muted/30 p-4 text-sm leading-6 text-muted-foreground">No placeholder server, Anti-Cheat, observer, screen-share, deployment or audit data is fabricated. This section becomes operational only after its scoped backend contract and trusted reporter are deployed.</div></CardContent></Card>}

    <Dialog open={workspaceOpen && Boolean(selectedPlayer)} onOpenChange={(open) => { if (!open && !busy) { setWorkspaceOpen(false); setActiveAction(null) } }}><DialogContent overlayClassName="bg-black/55 backdrop-blur-md" className="max-h-[calc(100dvh-2rem)] max-w-4xl overflow-y-auto bg-card/95 p-0 shadow-2xl backdrop-blur-2xl"><div className="border-b border-border px-6 py-5"><DialogHeader><DialogTitle className="flex items-center gap-2"><ShieldAlert className="h-5 w-5 text-primary" />Player action workspace</DialogTitle><DialogDescription>{selectedPlayer?.name} · {selectedPlayer?.steamId} · {selectedPlayer && teamLabel(selectedPlayer.team)}</DialogDescription></DialogHeader></div><div className="grid gap-5 p-6 lg:grid-cols-[.92fr_1.08fr]"><section><p className="mb-2 text-xs font-semibold uppercase tracking-[.15em] text-muted-foreground">Choose action</p><div className="grid grid-cols-2 gap-2">{playerActions.map((action) => { const Icon = action.icon; return <Button key={action.type} type="button" disabled={busy} onClick={() => chooseAction(action)} variant={action.destructive ? "outline" : "secondary"} className="h-auto justify-start gap-2 px-3 py-3 text-left"><Icon className="h-4 w-4" />{action.label}</Button> })}</div><div className="mt-5 rounded-lg border border-border bg-background/35 p-3"><div className="mb-2 flex items-center gap-2"><History className="h-4 w-4 text-muted-foreground" /><p className="text-sm font-medium text-foreground">Penalties history</p></div>{penaltiesLoading ? <div className="flex items-center gap-2 text-xs text-muted-foreground"><Loader2 className="h-3.5 w-3.5 animate-spin" />Loading canonical penalties</div> : penalties.length ? <div className="space-y-2">{penalties.slice(0, 5).map((penalty) => <div key={penalty.id} className={`rounded-md border p-2 text-xs ${penaltyTone(penalty)}`}><div className="flex justify-between gap-2"><span className="font-semibold uppercase">{penalty.type}</span><span>{penalty.isUnbanned ? "unbanned" : penalty.term}</span></div><p className="mt-1 line-clamp-2">{penalty.reason || "No reason recorded"}</p><p className="mt-1 opacity-70">{penalty.date ? new Date(penalty.date).toLocaleDateString() : "—"}</p></div>)}</div> : <p className="text-xs text-muted-foreground">No canonical penalties found for this identity.</p>}</div></section><section className="rounded-xl border border-border bg-background/30 p-4">{!activeAction && <div className="flex min-h-64 items-center justify-center text-center text-sm text-muted-foreground">Choose an action, then configure only the allowed fields.</div>}{activeAction?.workflow === "ban" && <div className="space-y-3"><p className="font-medium text-foreground">Configure ban</p><div className="grid gap-3 sm:grid-cols-2"><div><Label className="mb-1.5 block">Ban term</Label><select value={banTerm} onChange={(event) => setBanTerm(event.target.value as typeof banTerm)} className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm">{banTerms.map((term) => <option key={term}>{term}</option>)}</select></div><div className="rounded-lg border border-amber-300/25 bg-amber-300/[0.07] p-3 text-xs text-amber-100"><p className="font-medium">Player HUD</p><p className="mt-1">{actorLabel} banned you · enforcement starts in 10 seconds.</p></div></div><Label className="mb-1.5 block">Reason</Label><Textarea value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Explain the moderation reason" /></div>}{activeAction?.workflow === "reason" && <div className="space-y-3"><p className="font-medium text-foreground">Configure {activeAction.label}</p><Label className="mb-1.5 block">Reason</Label><Textarea value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Explain this moderation action" /></div>}{activeAction?.workflow === "mute" && <div className="grid gap-3 sm:grid-cols-2"><div><Label className="mb-1.5 block">Mute duration</Label><select value={muteDuration} onChange={(event) => setMuteDuration(event.target.value)} className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm"><option value="300">5 minutes</option><option value="1800">30 minutes</option><option value="3600">1 hour</option><option value="86400">1 day</option></select></div><div><Label className="mb-1.5 block">Reason</Label><Input value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Communication restriction reason" /></div></div>}{activeAction?.workflow === "rename" && <div><Label className="mb-1.5 block">New player name</Label><Input value={newName} onChange={(event) => setNewName(event.target.value)} placeholder="New display name" /></div>}{["hud", "message"].includes(activeAction?.workflow || "") && <div className="space-y-3"><Label className="mb-1.5 block">{activeAction?.workflow === "hud" ? "HUD text" : "Message"}</Label><Textarea value={message} onChange={(event) => setMessage(event.target.value)} placeholder="Write player-facing text" />{activeAction?.workflow === "hud" && <div className="grid gap-3 sm:grid-cols-2"><div><Label className="mb-1.5 block">Alert color</Label><div className="flex flex-wrap gap-2">{alertColors.map((color) => <Button key={color} type="button" size="sm" variant={alertColor === color ? "default" : "outline"} onClick={() => setAlertColor(color)} className="capitalize">{color}</Button>)}</div></div><div><Label className="mb-1.5 block">Countdown seconds</Label><Input value={countdownSeconds} onChange={(event) => setCountdownSeconds(event.target.value)} inputMode="numeric" /></div></div>}</div>}{activeAction?.workflow === "none" && <div className="rounded-lg border border-border bg-muted/30 p-3 text-sm text-muted-foreground">This request has no browser command fields. Its target is reviewed before queueing.</div>}{activeAction && <div className="mt-5 flex justify-end gap-2 border-t border-border pt-4"><Button type="button" variant="outline" onClick={() => setActiveAction(null)}>Back</Button><Button type="button" onClick={requestConfirmation}>Review and confirm</Button></div>}</section></div></DialogContent></Dialog>
    <AlertDialog open={Boolean(pendingAction)} onOpenChange={(open) => { if (!open && !busy) setPendingAction(null) }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle className="flex items-center gap-2"><AlertTriangle className="h-5 w-5" />Confirm queued operation</AlertDialogTitle><AlertDialogDescription>{pendingAction?.destructive ? "This operation affects a player, a match or server availability." : "Review the target and player-facing content before queueing."}</AlertDialogDescription></AlertDialogHeader><div className="space-y-2 rounded-lg border border-border bg-muted/30 p-3 text-sm"><p><span className="text-muted-foreground">Operation:</span> {pendingAction?.label}</p><p><span className="text-muted-foreground">Server:</span> {pendingAction?.type === "restart_all" ? `All configured servers; queue context: ${selectedServerName}` : selectedServerName}</p>{pendingAction?.scope === "player" && <p><span className="text-muted-foreground">Player:</span> {selectedPlayer?.name} · {selectedPlayer?.steamId}</p>}{pendingAction?.type === "ban" && <><p><span className="text-muted-foreground">Term:</span> {banTerm}</p><p><span className="text-muted-foreground">Reason:</span> {reason}</p><p className="rounded-md border border-amber-300/25 bg-amber-300/[0.07] p-2 text-amber-100">Player HUD: {actorLabel} banned you · enforcement starts in 10 seconds.</p></>}{pendingAction?.type === "kick" && <><p><span className="text-muted-foreground">Reason:</span> {reason}</p><p className="rounded-md border border-border bg-background/40 p-2 text-muted-foreground">Player notice: {actorLabel} will remove you. Reason: {reason}</p></>}{pendingAction?.workflow === "timeout" && <p><span className="text-muted-foreground">Timeout:</span> {timeoutDuration} seconds</p>}{pendingAction?.type === "unpause" && <p className="rounded-md border border-border bg-background/40 p-2 text-muted-foreground">The executor must verify an active pause before resuming the match.</p>}{pendingAction?.workflow === "map" && <><p><span className="text-muted-foreground">Map:</span> {cs2MapLabel(map)} ({map})</p><p className="rounded-md border border-amber-300/25 bg-amber-300/[0.07] p-2 text-amber-100">Impact acknowledged: the selected server will be interrupted. The plugin revalidates state before transition.</p></>}{pendingAction?.workflow === "rename" && <p><span className="text-muted-foreground">New name:</span> {newName}</p>}{["hud", "message"].includes(pendingAction?.workflow || "") && <><p><span className="text-muted-foreground">Text:</span> {message}</p>{pendingAction?.workflow === "hud" && <p><span className="text-muted-foreground">HUD style:</span> {alertColor} · {Number(countdownSeconds) || "no"} second countdown</p>}</>}<p className="pt-1 text-xs text-muted-foreground">This action is audited and remains pending until an authorized executor acknowledges it.</p></div><AlertDialogFooter><AlertDialogCancel disabled={busy}>Cancel</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={(event) => { event.preventDefault(); void queuePendingAction() }}>{busy ? "Queueing" : "Confirm and queue"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <AlertDialog open={Boolean(pendingArchive)} onOpenChange={(open) => { if (!open && !busy) setPendingArchive(null) }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Archive product</AlertDialogTitle><AlertDialogDescription>This hides the product from future purchases. Existing purchase history remains intact.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>Cancel</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={(event) => { event.preventDefault(); void archiveProduct() }}>{busy ? "Archiving" : "Confirm archive"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <AlertDialog open={pendingMaintenance !== null} onOpenChange={(open) => { if (!open && !busy) setPendingMaintenance(null) }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Confirm maintenance configuration</AlertDialogTitle><AlertDialogDescription>{pendingMaintenance ? "This saves an audited maintenance-on intent for legacyx.cc. It will not affect public traffic until the production website runtime consumes the setting." : "This saves an audited maintenance-off intent for legacyx.cc."}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>Cancel</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={(event) => { event.preventDefault(); void saveMaintenance() }}>{busy ? "Saving" : "Confirm configuration"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
  </main>
}
